"""Patch the android/ folder generated by `flutter create` for the Erriwaya app."""
import os
import re
import shutil
import sys

root = sys.argv[1] if len(sys.argv) > 1 else "."
main = os.path.join(root, "android", "app", "src", "main")
manifest_path = os.path.join(main, "AndroidManifest.xml")

with open(manifest_path, encoding="utf-8") as f:
    m = f.read()

# App name in Arabic.
m = re.sub(r'android:label="[^"]*"', 'android:label="الرواية"', m, count=1)

# Internet permission (release builds need it explicitly).
if "android.permission.INTERNET" not in m:
    m = m.replace(
        "<application",
        '<uses-permission android:name="android.permission.INTERNET"/>\n'
        '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>\n'
        "    <application",
        1,
    )

# Links: url_launcher needs <queries> on Android 11+.
if "<queries>" in m and "android.intent.action.VIEW" not in m.split("<queries>")[1]:
    m = m.replace(
        "<queries>",
        "<queries>\n        <intent>\n            <action android:name=\"android.intent.action.VIEW\" />\n"
        "            <data android:scheme=\"https\" />\n        </intent>",
        1,
    )
elif "<queries>" not in m:
    m = m.replace(
        "</manifest>",
        "    <queries>\n        <intent>\n            <action android:name=\"android.intent.action.VIEW\" />\n"
        "            <data android:scheme=\"https\" />\n        </intent>\n    </queries>\n</manifest>",
    )

# Notification icon + colour + channel for breaking news.
meta = (
    '        <meta-data android:name="com.google.firebase.messaging.default_notification_icon" '
    'android:resource="@drawable/ic_notification" />\n'
    '        <meta-data android:name="com.google.firebase.messaging.default_notification_color" '
    'android:resource="@color/erriwaya_green" />\n'
    '        <meta-data android:name="com.google.firebase.messaging.default_notification_channel_id" '
    'android:value="breaking" />\n'
)
if "default_notification_icon" not in m:
    m = re.sub(r"(<application[^>]*>\n)", lambda mm: mm.group(1) + meta, m, count=1)

with open(manifest_path, "w", encoding="utf-8") as f:
    f.write(m)

res = os.path.join(main, "res")
os.makedirs(os.path.join(res, "drawable"), exist_ok=True)
os.makedirs(os.path.join(res, "values"), exist_ok=True)
shutil.copy(os.path.join(root, "android-ci", "ic_notification.png"),
            os.path.join(res, "drawable", "ic_notification.png"))
with open(os.path.join(res, "values", "erriwaya_colors.xml"), "w", encoding="utf-8") as f:
    f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n'
            '    <color name="erriwaya_green">#004A49</color>\n</resources>\n')

# Launch screen in brand colour instead of white.
for name in ("drawable/launch_background.xml", "drawable-v21/launch_background.xml"):
    p = os.path.join(res, name)
    if os.path.exists(p):
        with open(p, "w", encoding="utf-8") as f:
            f.write('<?xml version="1.0" encoding="utf-8"?>\n'
                    '<layer-list xmlns:android="http://schemas.android.com/apk/res/android">\n'
                    '    <item android:drawable="@color/erriwaya_green" />\n</layer-list>\n')

print(open(manifest_path, encoding="utf-8").read())
